"const fs = require('fs');
const path = require('path');

const brainDir = 'C:\\Users\\user\\.gemini\\antigravity\\brain';

async function scanLogs() {
  try {
    const dirs = fs.readdirSync(brainDir);
    console.log(`Scanning ${dirs.length} conversation folders for 'subItems' or 'calculations'...`);

    let foundCount = 0;

    for (const dir of dirs) {
      const logPath = path.join(brainDir, dir, '.system_generated', 'logs', 'transcript.jsonl');
      if (!fs.existsSync(logPath)) continue;

      const fileContent = fs.readFileSync(logPath, 'utf8');
      const lines = fileContent.split('\n');

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        if (!line.trim()) continue;

        try {
          const obj = JSON.parse(line);
          const stringified = JSON.stringify(obj);

          if (stringified.includes('subItems') && (stringified.includes('calculation') || stringified.includes('calculations'))) {
            console.log(`\n🎉 MATCH FOUND! Dir: ${dir}, Step: ${obj.step_index}`);
            // Save match snippet
            fs.writeFileSync(`scratch/recovered_subitems_${dir}_step${obj.step_index}.json`, JSON.stringify(obj, null, 2), 'utf8');
            foundCount++;
          }
        } catch (e) {
          // ignore
        }
      }
    }

    console.log(`Scan completed. Found ${foundCount} subItems datasets.`);
  } catch (err) {
    console.error('Scan failed:', err);
  }
}

scanLogs();
"
